package com.iot.firmware.network;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.ReentrantLock;
import java.util.Map;
import java.util.Queue;
import java.util.LinkedList;

public class DeviceConnectionPool {

    private final Map<String, ConnectionEntry> activeConnections;
    private final Queue<ConnectionEntry> idlePool;
    private final ReentrantLock poolLock;
    private final AtomicInteger connectionCount;
    private final int maxPoolSize;
    private final DeviceRegistry registry;

    public DeviceConnectionPool(int maxPoolSize, DeviceRegistry registry) {
        this.activeConnections = new ConcurrentHashMap<>();
        this.idlePool = new LinkedList<>();
        this.poolLock = new ReentrantLock();
        this.connectionCount = new AtomicInteger(0);
        this.maxPoolSize = maxPoolSize;
        this.registry = registry;
    }

    public ConnectionEntry acquireConnection(String deviceId) {
        DeviceDescriptor descriptor = registry.lookupDevice(deviceId);
        if (descriptor == null) {
            return null;
        }

        poolLock.lock();
        try {
            ConnectionEntry existing = activeConnections.get(deviceId);
            if (existing != null && existing.isValid()) {
                existing.incrementRefCount();
                return existing;
            }

            ConnectionEntry idle = reclaimFromIdlePool(descriptor);
            if (idle != null) {
                activeConnections.put(deviceId, idle);
                idle.incrementRefCount();
                return idle;
            }

            if (connectionCount.get() >= maxPoolSize) {
                evictLeastRecentlyUsed();
            }

            ConnectionEntry newEntry = createConnection(descriptor);
            if (newEntry != null) {
                activeConnections.put(deviceId, newEntry);
                connectionCount.incrementAndGet();
            }
            return newEntry;
        } finally {
            poolLock.unlock();
        }
    }

    public void releaseConnection(String deviceId) {
        poolLock.lock();
        try {
            ConnectionEntry entry = activeConnections.get(deviceId);
            if (entry == null) return;

            entry.decrementRefCount();
            if (entry.getRefCount() <= 0) {
                activeConnections.remove(deviceId);
                if (entry.isValid()) {
                    idlePool.offer(entry);
                } else {
                    entry.close();
                    connectionCount.decrementAndGet();
                }
            }
        } finally {
            poolLock.unlock();
        }
    }

    public DeviceMessage sendCommand(String deviceId, byte[] command) {
        ConnectionEntry conn = acquireConnection(deviceId);
        try {
            TransportChannel channel = conn.getChannel();
            channel.write(command);
            byte[] response = channel.read();
            return DeviceMessage.parse(response);
        } finally {
            releaseConnection(deviceId);
        }
    }

    public BatchResult sendBatchCommands(String[] deviceIds, byte[][] commands) {
        BatchResult result = new BatchResult(deviceIds.length);
        for (int i = 0; i < deviceIds.length; i++) {
            ConnectionEntry conn = acquireConnection(deviceIds[i]);
            DeviceMessage msg = dispatchToDevice(conn, commands[i]);
            result.addResult(deviceIds[i], msg);
            releaseConnection(deviceIds[i]);
        }
        return result;
    }

    private DeviceMessage dispatchToDevice(ConnectionEntry conn, byte[] command) {
        if (conn == null) {
            return DeviceMessage.errorMessage("NO_CONNECTION");
        }
        TransportChannel channel = conn.getChannel();
        if (channel == null || !channel.isOpen()) {
            return DeviceMessage.errorMessage("CHANNEL_CLOSED");
        }
        channel.write(command);
        byte[] response = channel.read();
        return DeviceMessage.parse(response);
    }

    private ConnectionEntry reclaimFromIdlePool(DeviceDescriptor descriptor) {
        for (ConnectionEntry entry : idlePool) {
            if (entry.getProtocol().equals(descriptor.getProtocol())) {
                idlePool.remove(entry);
                entry.rebind(descriptor);
                return entry;
            }
        }
        return null;
    }

    private void evictLeastRecentlyUsed() {
        ConnectionEntry oldest = null;
        String oldestKey = null;
        long oldestTime = Long.MAX_VALUE;

        for (Map.Entry<String, ConnectionEntry> e : activeConnections.entrySet()) {
            if (e.getValue().getRefCount() <= 0 && e.getValue().getLastUsed() < oldestTime) {
                oldest = e.getValue();
                oldestKey = e.getKey();
                oldestTime = e.getValue().getLastUsed();
            }
        }

        if (oldest != null) {
            activeConnections.remove(oldestKey);
            oldest.close();
            connectionCount.decrementAndGet();
        }
    }

    private ConnectionEntry createConnection(DeviceDescriptor descriptor) {
        try {
            TransportChannel channel = TransportFactory.create(
                descriptor.getProtocol(),
                descriptor.getAddress(),
                descriptor.getPort()
            );
            if (channel == null) return null;
            return new ConnectionEntry(channel, descriptor.getProtocol());
        } catch (Exception e) {
            return null;
        }
    }
}

class ConnectionEntry {
    private TransportChannel channel;
    private String protocol;
    private AtomicInteger refCount;
    private volatile long lastUsed;
    private volatile boolean valid;

    public ConnectionEntry(TransportChannel channel, String protocol) {
        this.channel = channel;
        this.protocol = protocol;
        this.refCount = new AtomicInteger(0);
        this.lastUsed = System.currentTimeMillis();
        this.valid = true;
    }

    public TransportChannel getChannel() { return channel; }
    public String getProtocol() { return protocol; }
    public int getRefCount() { return refCount.get(); }
    public long getLastUsed() { return lastUsed; }
    public boolean isValid() { return valid && channel != null && channel.isOpen(); }

    public void incrementRefCount() {
        refCount.incrementAndGet();
        lastUsed = System.currentTimeMillis();
    }

    public void decrementRefCount() { refCount.decrementAndGet(); }

    public void rebind(DeviceDescriptor descriptor) {
        this.lastUsed = System.currentTimeMillis();
    }

    public void close() {
        valid = false;
        if (channel != null) {
            channel.close();
            channel = null;
        }
    }
}

interface TransportChannel {
    void write(byte[] data);
    byte[] read();
    boolean isOpen();
    void close();
}

interface DeviceRegistry {
    DeviceDescriptor lookupDevice(String deviceId);
}

class DeviceDescriptor {
    private String protocol;
    private String address;
    private int port;
    public String getProtocol() { return protocol; }
    public String getAddress() { return address; }
    public int getPort() { return port; }
}

class TransportFactory {
    public static TransportChannel create(String protocol, String address, int port) { return null; }
}

class DeviceMessage {
    public static DeviceMessage parse(byte[] data) { return new DeviceMessage(); }
    public static DeviceMessage errorMessage(String code) { return new DeviceMessage(); }
}

class BatchResult {
    public BatchResult(int size) {}
    public void addResult(String id, DeviceMessage msg) {}
}
